#include <CoreText/CoreText.h>
#include <stdio.h>
int main(void) {
 const char *names[]={"TimesNewRomanPSMT","ArialMT","CourierNewPSMT"};
 double sizes[]={8.5,10,10.5,12,13,18,21.5};
 puts("["); int first=1;
 for(int f=0;f<3;f++) for(int s=0;s<7;s++) {
  CFStringRef name=CFStringCreateWithCString(NULL,names[f],kCFStringEncodingUTF8);
  CTFontRef font=CTFontCreateWithName(name,sizes[s],NULL);
  for(int script=-1;script<=1;script++) {
   CFNumberRef number=CFNumberCreate(NULL,kCFNumberIntType,&script);
   const void *keys[]={kCTFontAttributeName,kCTSuperscriptAttributeName};
   const void *values[]={font,number};
   CFDictionaryRef attrs=CFDictionaryCreate(NULL,keys,values,2,&kCFTypeDictionaryKeyCallBacks,&kCFTypeDictionaryValueCallBacks);
   CFAttributedStringRef str=CFAttributedStringCreate(NULL,CFSTR("HHHHHH"),attrs);
   CTLineRef line=CTLineCreateWithAttributedString(str);
   CFArrayRef runs=CTLineGetGlyphRuns(line);
   for(CFIndex r=0;r<CFArrayGetCount(runs);r++) {
    CTRunRef run=CFArrayGetValueAtIndex(runs,r);
    CGPoint pos; CTRunGetPositions(run,CFRangeMake(0,1),&pos);
    CFDictionaryRef actualAttrs=CTRunGetAttributes(run);
    CTFontRef actualFont=CFDictionaryGetValue(actualAttrs,kCTFontAttributeName);
    CGAffineTransform m=CTRunGetTextMatrix(run);
    if(!first) puts(",");first=0;
    printf("{\"font\":\"%s\",\"size\":%.9g,\"script\":%d,\"fontSize\":%.9g,\"origin\":[%.9g,%.9g],\"matrix\":[%.9g,%.9g,%.9g,%.9g,%.9g,%.9g],\"advance\":%.9g,\"ascent\":%.9g,\"descent\":%.9g,\"leading\":%.9g,\"capHeight\":%.9g,\"xHeight\":%.9g}",names[f],sizes[s],script,CTFontGetSize(actualFont),pos.x,pos.y,m.a,m.b,m.c,m.d,m.tx,m.ty,CTRunGetTypographicBounds(run,CFRangeMake(0,0),NULL,NULL,NULL),CTFontGetAscent(font),CTFontGetDescent(font),CTFontGetLeading(font),CTFontGetCapHeight(font),CTFontGetXHeight(font));
   }
   CFRelease(line);CFRelease(str);CFRelease(attrs);CFRelease(number);
  }
  CFRelease(font);CFRelease(name);
 }
 puts("\n]"); return 0;
}

