#import <AppKit/AppKit.h>
#include <math.h>
#include <stdio.h>
int main(void) { @autoreleasepool {
 NSArray *names=@[@"TimesNewRomanPSMT",@"ArialMT",@"CourierNewPSMT"];
 double sizes[]={8.5,10,10.5,12,13,18,21.5}; int first=1;
 puts("[");
 for(NSString *name in names) for(int si=0;si<7;si++) for(int suppliedSmall=0;suppliedSmall<2;suppliedSmall++) for(int level=-1;level<=1;level+=2) {
  double size=sizes[si]; NSFont *font=[NSFont fontWithName:name size:size];
  NSMutableAttributedString *str=[[NSMutableAttributedString alloc] initWithString:@"AHHHHHHB" attributes:@{NSFontAttributeName:font}];
  [str addAttribute:NSSuperscriptAttributeName value:@(level) range:NSMakeRange(1,6)];
  if(suppliedSmall) [str addAttribute:NSFontAttributeName value:[NSFont fontWithName:name size:floor(size*.65*2+.5)/2] range:NSMakeRange(1,6)];
  NSTextStorage *store=[[NSTextStorage alloc] initWithAttributedString:str];
  NSLayoutManager *manager=[[NSLayoutManager alloc] init];
  NSTextContainer *container=[[NSTextContainer alloc] initWithContainerSize:NSMakeSize(1000,1000)];
  [store addLayoutManager:manager]; [manager addTextContainer:container];
  [manager ensureLayoutForTextContainer:container];
  NSPoint a=[manager locationForGlyphAtIndex:0], h=[manager locationForGlyphAtIndex:1], b=[manager locationForGlyphAtIndex:7];
  if(!first)puts(",");first=0;
  printf("{\"font\":\"%s\",\"size\":%.9g,\"suppliedSmall\":%s,\"script\":%d,\"A\":[%.9g,%.9g],\"H\":[%.9g,%.9g],\"B\":[%.9g,%.9g],\"rise\":%.9g}",[name UTF8String],size,suppliedSmall?"true":"false",level,a.x,a.y,h.x,h.y,b.x,b.y,a.y-h.y);
 }
 puts("\n]"); return 0;
}}
